
-- Table 1 - scan: save scanned images dir with scan id
CREATE TABLE "scan" (
  "scan_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "image_path" text NOT NULL,
  "created_at" timestamp DEFAULT (now())
);

-- Table 2 - books: save all the detected books with metadata; this could be used for other purposes later.
CREATE TABLE "books" (
  "book_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "scan_id" integer NOT NULL,
  "work_id" varchar(30),
  "title" text,
  "authors" TEXT[] NOT NULL DEFAULT '{}',
  "description" text,
  "subjects" TEXT[] NOT NULL DEFAULT '{}',
  "registered_at" timestamp DEFAULT (now())
);

-- Table 3 - recommendation_result: save the results of the recommendation engine.
CREATE TABLE "recommendation_result" (
  "result_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "scan_id" integer NOT NULL,
  "model_name" varchar(150) NOT NULL,
  "preference_text" text NOT NULL,
  "top_k" integer NOT NULL,
  "ranked_outcome" jsonb NOT NULL,
  "created_at" timestamp DEFAULT (now())
);

ALTER TABLE "books" ADD FOREIGN KEY ("scan_id") REFERENCES "scan" ("scan_id") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "recommendation_result" ADD FOREIGN KEY ("scan_id") REFERENCES "scan" ("scan_id") DEFERRABLE INITIALLY IMMEDIATE;
